function opts(e,a,p){if(e)e.innerHTML='<option value="">'+esc(p)+'</option>'+a.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')}
function toast(msg,type='info'){const e=$('#cs-toast');if(!e)return;e.textContent=msg;e.dataset.type=type;e.classList.add('show');clearTimeout(window.__urbion_toast);window.__urbion_toast=setTimeout(()=>e.classList.remove('show'),2600)}
function complete(){return ['project_name','lat','lon','state','pbt','district','landuse','category','activity','development','ratio'].every(val)}
function payload(){return{project_name:val('project_name'),site_lat:num('lat'),site_lon:num('lon'),tod_lat:num('todlat'),tod_lon:num('todlon'),state:val('state'),pbt:val('pbt'),district:val('district'),lot_no:val('lot'),project_reference:val('project_reference'),land_use:val('landuse'),landuse:val('landuse'),development_class:val('category'),category:val('category'),activity:val('activity'),development_type:val('development'),development:val('development'),plot_ratio:num('ratio')}}
function sync(){const ids=['project_name','lat','lon','state','pbt','district','landuse','category','activity','development','ratio'],n=ids.filter(val).length,p=Math.round(n/ids.length*100);$('#cs-ready').textContent=p+'%';$('#cs-ready-bar').style.width=p+'%';$('#cs-run').disabled=!complete()||busy;$('#cs-status-pill').textContent=busy?'PROCESSING':assessment?'ANALYSIS READY':complete()?'READY TO RUN':'CASE INCOMPLETE';$('#cs-case-title').textContent=val('project_name')||'New planning case';$('#cs-case-meta').textContent=[val('state'),val('district'),val('pbt')].filter(Boolean).join(' · ')||'Location not defined'}
function cascade(){const s=id('state'),p=id('pbt'),d=id('district');opts(p,PBTS[s.value]||[],'Select PBT');opts(d,DISTRICTS[s.value]||[],'Select district');s.onchange=()=>{opts(p,PBTS[s.value]||[],'Select PBT');opts(d,DISTRICTS[s.value]||[],'Select district');sync()};p.onchange=sync;d.onchange=sync}
function hierarchy(){const l=id('landuse'),c=id('category'),a=id('activity');opts(l,Object.keys(LANDUSE),'Select Guna Tanah 1');opts(c,[],'Select Guna Tanah 2');opts(a,[],'Select Guna Tanah 3');l.onchange=()=>{opts(c,Object.keys(LANDUSE[l.value]||{}),'Select Guna Tanah 2');opts(a,[],'Select Guna Tanah 3');sync()};c.onchange=()=>{opts(a,LANDUSE[l.value]?.[c.value]||[],'Select Guna Tanah 3');sync()};a.onchange=sync}
function field(label,html){return'<label class="field"><span>'+label+'</span>'+html+'</label>'}
